package com.mantou.salesdialer.contacts;
import java.util.*;
import com.mantou.salesdialer.contacts.PhoneIntakeModel.*;
public final class LocalDraftBindingCheck {
 static int checks;static void eq(Object a,Object b){checks++;if(!Objects.equals(a,b))throw new AssertionError("DRAFT_ASSERTION_"+checks);}static void fail(Runnable r,String msg){checks++;try{r.run();}catch(RuntimeException e){if(msg.equals(e.getMessage()))return;throw new AssertionError(e);}throw new AssertionError("EXPECTED_"+msg);}
 static LocalDraftBinding.Snapshot s(DataClass type,String slot,long rev,Qualification q,boolean refused){return LocalDraftBinding.snapshot(type,slot,"LOCAL-TARGET-"+"b".repeat(32),rev,q,refused,"DECLARED_LOCAL");}
 public static void main(String[] args){String slot="a".repeat(32);var s=s(DataClass.LOCAL_PHONE_INTAKE,slot,1,Qualification.CONFIRMED,false);var d=LocalDraftBinding.create(s);eq(d.contactRevision,1L);eq(d.targetId,s.targetId);eq(d.slot,slot);eq(d.dataClass,DataClass.LOCAL_PHONE_INTAKE);eq(d.productionAuthenticated,false);eq(d.realCallsEnabled,false);eq(LocalDraftBinding.status(s,d),"ELIGIBLE_FOR_PLANNING");eq(LocalDraftBinding.create(s).id,d.id);System.out.println("T672 explicit local drafts preserve immutable scope and never grant execution passed");
 var next=s(DataClass.LOCAL_PHONE_INTAKE,slot,2,Qualification.CONFIRMED,false);eq(LocalDraftBinding.status(next,d),"STALE_CONTACT");var fresh=LocalDraftBinding.refresh(next,d,2,1);eq(fresh.id,d.id);eq(fresh.contactRevision,2L);eq(d.contactRevision,1L);eq(LocalDraftBinding.refresh(next,fresh,2,1).contactRevision,2L);fail(()->LocalDraftBinding.refresh(next,d,1,1),"STALE_CONTACT");fail(()->LocalDraftBinding.refresh(next,d,2,2),"STALE_DRAFT");eq(LocalDraftBinding.restore(next,fresh.id,2).id,d.id);fail(()->LocalDraftBinding.restore(next,d.id,3),"INVALID_STORED_TASK");System.out.println("T673 explicit refresh reuses core CAS and old snapshots stay stale passed");
 for(Qualification q:List.of(Qualification.UNKNOWN,Qualification.WITHDRAWN)){var unqualified=s(DataClass.LOCAL_PHONE_INTAKE,slot,2,q,false);fail(()->LocalDraftBinding.create(unqualified),"CONTACT_NOT_QUALIFIED");fail(()->LocalDraftBinding.refresh(unqualified,d,2,1),"CONTACT_NOT_QUALIFIED");}var refused=s(DataClass.LOCAL_PHONE_INTAKE,slot,2,Qualification.CONFIRMED,true);fail(()->LocalDraftBinding.create(refused),"DO_NOT_CONTACT");fail(()->LocalDraftBinding.refresh(refused,d,2,1),"DO_NOT_CONTACT");System.out.println("T674 current qualification and refusal block create and refresh passed");
 var fixture=s(DataClass.FORMAT_FIXTURE,slot,1,Qualification.CONFIRMED,false);var other=s(DataClass.LOCAL_PHONE_INTAKE,"c".repeat(32),1,Qualification.CONFIRMED,false);eq(LocalDraftBinding.status(fixture,d),"FORBIDDEN");eq(LocalDraftBinding.status(other,d),"FORBIDDEN");fail(()->LocalDraftBinding.refresh(fixture,d,1,1),"FORBIDDEN");eq(LocalDraftBinding.create(fixture).id.equals(d.id),false);eq(LocalDraftBinding.create(other).id.equals(d.id),false);eq(LocalDraftBinding.create(fixture).realCallsEnabled,false);eq(PhoneIntakeModel.submissionBoundary(fixture.dataClass),"FORMAT_FIXTURE_ONLY");System.out.println("T675 data class and private slot cannot promote or alias drafts passed");
 fail(()->LocalDraftBinding.snapshot(null,slot,s.targetId,1,Qualification.CONFIRMED,false,"S"),"INVALID_LOCAL_SNAPSHOT");fail(()->LocalDraftBinding.snapshot(DataClass.LOCAL_PHONE_INTAKE,"bad",s.targetId,1,Qualification.CONFIRMED,false,"S"),"INVALID_LOCAL_SNAPSHOT");fail(()->LocalDraftBinding.snapshot(DataClass.LOCAL_PHONE_INTAKE,slot,"SIM-001",1,Qualification.CONFIRMED,false,"S"),"INVALID_LOCAL_SNAPSHOT");fail(()->s(DataClass.LOCAL_PHONE_INTAKE,slot,0,Qualification.CONFIRMED,false),"INVALID_LOCAL_SNAPSHOT");eq(LocalDraftBinding.status(s,null),"FORBIDDEN");System.out.println("T676 malformed bindings and absent draft fail closed passed");System.out.println("PASS: "+checks+" assertions; 5 local-draft scenarios; no telephone or plan");}
}
